// Port of src/lib/csv/ukgLeave.test.ts. The preamble's export name is neutral text here.

using Roster.Data.Feeds;

namespace Roster.Data.Tests.Feeds;

public class UkgLeaveTests
{
    // The preamble UKG writes above the table.
    private static readonly string Preamble = string.Join("\n",
        "Export Name:,Leave Liability-Export",
        "Generated By:,Jordan Lee",
        "Time Period:,Today",
        "Location:,All Home",
        "Sorted By:,Location Ascending",
        "Total Rows:,1875",
        "Currency:,NONE",
        "");

    [Fact]
    public void UkgNumber_reads_accounting_brackets_as_negative()
    {
        Assert.Equal(-69.48, UkgLeave.UkgNumber("(69.48)"));
        Assert.Equal(135.67, UkgLeave.UkgNumber("135.67"));
    }

    [Fact]
    public void UkgNumber_treats_blank_as_zero()
    {
        Assert.Equal(0, UkgLeave.UkgNumber(""));
        Assert.Equal(0, UkgLeave.UkgNumber(null));
    }

    [Fact]
    public void UkgNumber_strips_thousands_separators() => Assert.Equal(1361.48, UkgLeave.UkgNumber("1,361.48"));

    [Fact]
    public void UkgDate_reads_DD_MM_YYYY_with_a_trailing_time()
    {
        Assert.Equal("2026-12-26", UkgLeave.UkgDate("26-12-2026 12:00 AM"));
        Assert.Equal("2027-01-09", UkgLeave.UkgDate("09-01-2027 12:00 AM"));
    }

    [Fact]
    public void UkgDate_does_not_confuse_day_and_month() =>
        // 03-08 is 3 August, not 8 March.
        Assert.Equal("2026-08-03", UkgLeave.UkgDate("03-08-2026 12:00 AM"));

    [Fact]
    public void UkgDate_is_null_for_junk()
    {
        Assert.Null(UkgLeave.UkgDate(""));
        Assert.Null(UkgLeave.UkgDate("not a date"));
    }

    [Fact]
    public void Finds_the_header_row_by_content_not_by_a_fixed_line_count()
    {
        var csv = $"{Preamble}\nLocation,Employee Name,Employee ID\n505001,\"1-A, B\",990221";
        var (headers, rows) = UkgLeave.ParseUkgExport(csv, "Employee Name");
        Assert.Equal(["Location", "Employee Name", "Employee ID"], headers);
        Assert.Single(rows);
    }

    [Fact]
    public void Copes_when_the_preamble_grows_or_shrinks() =>
        Assert.Single(UkgLeave.ParseUkgExport("Export Name:,X\n\nLocation,Employee Name,Employee ID\n505001,\"1-A, B\",1", "Employee Name").Rows);

    private static readonly string Liability = string.Join("\n",
        Preamble,
        "StoreID,Location,Employee Name,Employee ID,Job,Contract Hrs,Notional Hrs,Sick Lve Accrued,Annual Lve Accrued,Lieu Hrs Accrued,Banked Hrs Accrued,Banked 2 Hrs Accrued",
        "G001,505001,\"1-Archer, Val\",990221,ST MANAGER,90.00,9.00,141.37,135.67,(69.48),,",
        "G001,505001,\"3-Duty, D\",200001,ST DUTY STORE MANAGER,70.00,7.50,10.00,50.00,,,",
        "G001,505001,\"5-Assist, A\",200002,ST ASSIST,70.00,7.25,5.00,40.00,,,",
        "G001,505001,\"6C-Casual, C\",200003,ST ASSIST JNR CASUAL,0.00,0.00,0.00,0.00,,,");

    [Fact]
    public void Liability_maps_jobs_to_entitlement_classes() =>
        Assert.Equal(["SM", "DSM", "SA", "CASUAL"], UkgLeave.ParseLiability(Liability).Rows.Select(r => r.RoleClass));

    [Fact]
    public void Liability_keeps_the_two_70_hour_rows_distinguishable_by_role() =>
        Assert.Equal(["DSM", "SA"], UkgLeave.ParseLiability(Liability).Rows.Where(r => r.ContractHours == 70).Select(r => r.RoleClass));

    [Fact]
    public void Liability_reads_bracketed_lieu_hours_as_negative_and_blanks_as_zero()
    {
        var rows = UkgLeave.ParseLiability(Liability).Rows;
        Assert.Equal(-69.48, rows[0].LieuHours);
        Assert.Equal(0, rows[0].BankedHours);
    }

    [Fact]
    public void Liability_reports_the_store_codes_present() =>
        Assert.Equal(["G001"], UkgLeave.ParseLiability(Liability).StoreCodes);

    [Fact]
    public void Liability_rejects_a_row_with_no_StoreID_rather_than_guessing()
    {
        var bad = string.Join("\n", Preamble, "StoreID,Employee Name,Employee ID,Job,Contract Hrs", ",\"1-A, B\",1,ST MANAGER,90.00");
        var parsed = UkgLeave.ParseLiability(bad);
        Assert.Empty(parsed.Rows);
        Assert.Contains("StoreID", parsed.Errors[0].Message);
    }

    private static readonly string Requests = string.Join("\n",
        Preamble,
        "StoreID,Location,Employee ID,Employee Name,Leave Type,Start Date,End Date,Status,Approver",
        "G001,505055,990636,\"1-Cole, Jesse\",REQ - Annual Leave,26-12-2026 12:00 AM,09-01-2027 12:00 AM,Approved,\"1-Cole, Jesse\"",
        "G001,505055,990636,\"1-Cole, Jesse\",REQ - Unpaid Leave,01-03-2027 12:00 AM,02-03-2027 12:00 AM,Approved,");

    [Fact]
    public void Requests_parses_both_rows_including_the_unpaid_one_the_workbook_dropped()
    {
        var rows = UkgLeave.ParseLeaveRequests(Requests).Rows;
        Assert.Equal(2, rows.Count);
        Assert.Equal("REQ - Unpaid Leave", rows[1].LeaveType);
    }

    [Fact]
    public void Requests_normalises_the_dates()
    {
        var rows = UkgLeave.ParseLeaveRequests(Requests).Rows;
        Assert.Equal(new DateOnly(2026, 12, 26), rows[0].StartDate);
        Assert.Equal(new DateOnly(2027, 1, 9), rows[0].EndDate);
    }

    [Fact]
    public void Requests_rejects_an_end_date_before_its_start()
    {
        var bad = string.Join("\n", Preamble,
            "StoreID,Employee ID,Employee Name,Leave Type,Start Date,End Date,Status",
            "G001,1,A,REQ - Annual Leave,10-08-2026 12:00 AM,01-08-2026 12:00 AM,Approved");
        var parsed = UkgLeave.ParseLeaveRequests(bad);
        Assert.Empty(parsed.Rows);
        Assert.Contains("before", parsed.Errors[0].Message);
    }
}
